          svg: `<svg viewBox="0 0 1100 1100" xmlns="http://www.w3.org/2000/svg"><rect width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="60" text-anchor="middle" fill="#ffd700" font-size="32" font-weight="bold">The Patron Network</text><circle cx="550" cy="550" r="80" fill="#ffd700"/><text x="550" y="545" text-anchor="middle" fill="#1a1a2e" font-size="18" font-weight="bold">BEETHOVEN</text><text x="550" y="575" text-anchor="middle" fill="#1a1a2e" font-size="14">Vienna</text><circle cx="250" cy="250" r="65" fill="#6366f1" opacity="0.5"/><text x="250" y="240" text-anchor="middle" fill="#ffffff" font-size="14" font-weight="bold">LICHNOWSKY</text><text x="250" y="265" text-anchor="middle" fill="#ffffff" font-size="12">Op. 13, Sym 2</text><text x="250" y="285" text-anchor="middle" fill="#888" font-size="11">first major patron</text><line x1="310" y1="290" x2="490" y2="510" stroke="#6366f1" stroke-width="2"/><circle cx="550" cy="200" r="70" fill="#ef4444" opacity="0.5"/><text x="550" y="190" text-anchor="middle" fill="#ffffff" font-size="14" font-weight="bold">LOBKOWITZ</text><text x="550" y="215" text-anchor="middle" fill="#ffffff" font-size="12">Eroica, Op.18</text><text x="550" y="235" text-anchor="middle" fill="#888" font-size="11">private orchestra</text><line x1="550" y1="270" x2="550" y2="470" stroke="#ef4444" stroke-width="2"/><circle cx="850" cy="250" r="65" fill="#10b981" opacity="0.5"/><text x="850" y="240" text-anchor="middle" fill="#ffffff" font-size="14" font-weight="bold">RAZUMOVSKY</text><text x="850" y="265" text-anchor="middle" fill="#ffffff" font-size="12">Op. 59 quartets</text><text x="850" y="285" text-anchor="middle" fill="#888" font-size="11">Russian ambassador</text><line x1="790" y1="290" x2="610" y2="510" stroke="#10b981" stroke-width="2"/><circle cx="200" cy="600" r="75" fill="#ec4899" opacity="0.5"/><text x="200" y="585" text-anchor="middle" fill="#ffffff" font-size="14" font-weight="bold">ARCHDUKE</text><text x="200" y="605" text-anchor="middle" fill="#ffffff" font-size="14" font-weight="bold">RUDOLPH</text><text x="200" y="630" text-anchor="middle" fill="#ffffff" font-size="12">14 dedications</text><text x="200" y="650" text-anchor="middle" fill="#888" font-size="11">emperor's brother</text><line x1="275" y1="615" x2="470" y2="555" stroke="#ec4899" stroke-width="3"/><circle cx="900" cy="600" r="60" fill="#f59e0b" opacity="0.5"/><text x="900" y="595" text-anchor="middle" fill="#ffffff" font-size="14" font-weight="bold">KINSKY</text><text x="900" y="620" text-anchor="middle" fill="#ffffff" font-size="12">1800 fl./yr</text><text x="900" y="640" text-anchor="middle" fill="#888" font-size="11">d. age 31</text><line x1="840" y1="610" x2="630" y2="565" stroke="#f59e0b" stroke-width="2"/><circle cx="350" cy="900" r="55" fill="#0ea5e9" opacity="0.5"/><text x="350" y="895" text-anchor="middle" fill="#ffffff" font-size="13" font-weight="bold">WALDSTEIN</text><text x="350" y="915" text-anchor="middle" fill="#ffffff" font-size="11">Op. 53</text><text x="350" y="933" text-anchor="middle" fill="#888" font-size="11">Bonn era</text><line x1="395" y1="850" x2="500" y2="620" stroke="#0ea5e9" stroke-width="2"/><circle cx="750" cy="900" r="55" fill="#8b5cf6" opacity="0.5"/><text x="750" y="895" text-anchor="middle" fill="#ffffff" font-size="13" font-weight="bold">ERDODY</text><text x="750" y="915" text-anchor="middle" fill="#ffffff" font-size="11">Op. 70</text><text x="750" y="933" text-anchor="middle" fill="#888" font-size="11">close friend</text><line x1="705" y1="850" x2="600" y2="620" stroke="#8b5cf6" stroke-width="2"/><rect x="200" y="990" width="700" height="60" fill="#ffd700" opacity="0.2"/><text x="550" y="1030" text-anchor="middle" fill="#ffd700" font-size="18" font-weight="bold">1809 stipend: Rudolph + Lobkowitz + Kinsky = 4,000 fl./yr</text></svg>`,
