          svg: `<svg viewBox="0 0 1100 1100" xmlns="http://www.w3.org/2000/svg"><rect width="1100" height="1100" fill="#1a1a2e"/><text x="550" y="80" text-anchor="middle" fill="#ffd700" font-size="32" font-weight="bold">The 1809 Contract</text><rect x="200" y="160" width="700" height="320" fill="#ffd700" opacity="0.1" stroke="#ffd700" stroke-width="3"/><text x="550" y="210" text-anchor="middle" fill="#ffd700" font-size="22" font-weight="bold">4,000 florins per year</text><line x1="240" y1="240" x2="860" y2="240" stroke="#ffffff" stroke-width="1"/><text x="280" y="290" fill="#ffffff" font-size="18">Archduke Rudolph:</text><text x="700" y="290" fill="#ffd700" font-size="18" text-anchor="end">1,500 fl.</text><text x="280" y="330" fill="#ffffff" font-size="18">Prince Lobkowitz:</text><text x="700" y="330" fill="#ffd700" font-size="18" text-anchor="end">700 fl.</text><text x="280" y="370" fill="#ffffff" font-size="18">Prince Kinsky:</text><text x="700" y="370" fill="#ffd700" font-size="18" text-anchor="end">1,800 fl.</text><line x1="240" y1="410" x2="860" y2="410" stroke="#ffffff" stroke-width="2"/><text x="280" y="450" fill="#ffd700" font-size="20" font-weight="bold">For:</text><text x="700" y="450" fill="#ffd700" font-size="20" font-weight="bold" text-anchor="end">NOTHING</text><rect x="100" y="540" width="900" height="240" fill="none" stroke="#10b981" stroke-width="2"/><text x="550" y="580" text-anchor="middle" fill="#10b981" font-size="22" font-weight="bold">What it bought</text><text x="120" y="630" fill="#ffffff" font-size="16">No specific compositions required</text><text x="120" y="665" fill="#ffffff" font-size="16">No teaching obligation</text><text x="120" y="700" fill="#ffffff" font-size="16">No livery</text><text x="120" y="735" fill="#ffffff" font-size="16">Just one promise: stay in Vienna and keep working</text><rect x="100" y="820" width="900" height="180" fill="#ec4899" opacity="0.2" stroke="#ec4899" stroke-width="3"/><text x="550" y="870" text-anchor="middle" fill="#ec4899" font-size="22" font-weight="bold">The Invention</text><text x="550" y="920" text-anchor="middle" fill="#ffffff" font-size="20">First contract of its kind in European history.</text><text x="550" y="960" text-anchor="middle" fill="#ffd700" font-size="20">The supported INDEPENDENT artist.</text></svg>`,
